var client = new ServiceBusClient(connectionString);
var receiver = client.CreateReceiver("orders", new ServiceBusReceiverOptions {
    ReceiveMode = ServiceBusReceiveMode.PeekLock });
ServiceBusReceivedMessage msg = await receiver.ReceiveMessageAsync(TimeSpan.FromSeconds(30));
try {
    await HandleAsync(msg.Body);                      // business commit first
    await receiver.CompleteMessageAsync(msg);         // ack -> broker deletes it
} catch (Exception) when (!msg.LockTokenExpired()) {
    await receiver.AbandonMessageAsync(msg);          // unlock -> redelivery
}

